import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Package i can be picked by day min(i+1, n-i): add packages by deadline, keep the best `day` in a min-heap.
        PriorityQueue<Long> heap = new PriorityQueue<>();
        for (int day = 1; day <= (n + 1) / 2; day++) {
            heap.add(a[day - 1]);
            if (day - 1 != n - day) heap.add(a[n - day]);
            while (heap.size() > day) heap.poll();
        }
        long total = 0;
        for (long v : heap) total += v;
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

type minHeap []int64

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(int64)) }
func (h *minHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// Package i can be picked by day min(i+1, n-i): add packages by deadline, keep the best `day` in a min-heap.
	h := &minHeap{}
	for day := 1; day <= (n+1)/2; day++ {
		heap.Push(h, a[day-1])
		if day-1 != n-day {
			heap.Push(h, a[n-day])
		}
		for h.Len() > day {
			heap.Pop(h)
		}
	}
	total := int64(0)
	for _, v := range *h {
		total += v
	}
	fmt.Println(total)
}
